function results = m3_observer_suite(null_mat_path, load_mat_path, varargin)
%M3_OBSERVER_SUITE Milestone M3 (Lane B) Generalized Momentum Observer Suite
%   Version: 2.0.0-PRELIMINARY (Post Code-to-Report Audit)
%   Project: IIT/SRIC/R/AEH/2026/104 (Electric Cable Shovel Digital Twin)
%   Status:  PRELIMINARY (Pending frozen MS02P05 configuration sweep signals)
%
%   PURPOSE:
%   Ingests and validates the actual Simscape MAT archives (M2_null.mat and
%   M2_100kN_0p1111Hz_sp1p50.mat) generated by recover_load.m, and compares
%   two 30 Hz Generalized Momentum Observer (GMO) branches for recovering
%   external generalized excavation loads tau_L = [tau_{L,3}; F_{L,4}]:
%
%     Branch A (Friction-Aware Continuous-Discrete Momentum Observer):
%       Explicitly includes the regularized M1 Coulomb friction model
%       F_c(dq) = [340*tanh(dq3/eps3); 480*tanh(dd4/eps4)] in the known
%       dynamics vector h_A, and integrates dz_A/dt = h_A(t) + K_O*(p(t) - z_A(t))
%       between 30 Hz measurement updates using linear interpolation (FOH)
%       and fine internal sub-stepping (1.0 ms, M=33 and 0.5 ms, M=67).
%
%     Branch B (Friction-Uncertainty Momentum Observer):
%       Deliberately omits Coulomb friction from the observer dynamics
%       h_B = tau_a - G(q) - F_v*dq + C(q,dq)'*dq, estimating the combined
%       disturbance tau_combined = tau_L - F_c(dq). Separates the deterministic
%       friction discrepancy bound (|tau_hat_A - tau_hat_B| <= f_c) from
%       dynamic observer tracking lag (tau_L - tau_{L,filt}), reporting:
%         1) Friction-Discrepancy Bound Coverage (CovFricPct)
%         2) Lag-Compensated External-Load Coverage (CovLagPct)
%         3) Raw Uncompensated External-Load Coverage (CovRawPct)
%
%   SIGN CONVENTION (Reconciled with shovel_params.m & recover_load.m):
%     M3 Plant Equation: D(q)*ddq + C(q,dq)*dq + G(q) + F_v*dq + F_c(dq) = tau_a + tau_L
%     recover_load.m:    D(q)*ddq + C(q,dq)*dq + G(q) + f = tau_actuator + Q_ext
%     Therefore, with tau_a = tau_actuator:
%       tau_L = +Q_ext = +J_s(q)' * F = [R.sig.Qq3_pred; R.sig.Qd4_pred]
%             = -e_tau = -[R.sig.ref3; R.sig.ref4].
%
%   DATA INGESTION & FAILURE POLICY:
%     By default ('Mode', 'mat_archive'), this function loads and validates
%     the supplied MAT archives (checking file existence, R.sig variable
%     completeness, units, timestamps, monotonicity, sampling rate, and
%     parameter consistency with shovel_params.m). If a summary-only MAT
%     file (such as stage1_results.mat) or missing/corrupt archive is passed,
%     execution fails immediately with a clear diagnostic error and NEVER
%     falls back silently to reconstructed or synthetic data.
%     A separate synthetic trajectory mode ('Mode', 'synthetic_unit_test')
%     is preserved strictly for standalone unit testing when explicitly
%     requested by the caller.
%
%   USAGE:
%     results = m3_observer_suite();
%     results = m3_observer_suite('M2_null.mat', 'M2_100kN_0p1111Hz_sp1p50.mat');
%     results = m3_observer_suite('', '', 'Mode', 'synthetic_unit_test');

    ip = inputParser;
    ip.addOptional('null_mat_path', 'M2_null.mat', @ischar);
    ip.addOptional('load_mat_path', 'M2_100kN_0p1111Hz_sp1p50.mat', @ischar);
    ip.addParameter('Mode', 'mat_archive', @(x) any(validatestring(x, {'mat_archive', 'synthetic_unit_test'})));
    ip.addParameter('FrozenGain', 20.0, @(x) isscalar(x) && isnumeric(x) && x > 0);
    ip.addParameter('SubSteps', 67, @(x) isscalar(x) && isnumeric(x) && x >= 1);
    ip.addParameter('RngSeed', 202603, @(x) isscalar(x) && isnumeric(x));
    ip.addParameter('SaveResults', true, @islogical);
    ip.addParameter('OutFile', 'M3_observer_audit_results.mat', @ischar);
    ip.parse(null_mat_path, load_mat_path, varargin{:});
    opt = ip.Results;

    fprintf('======================================================================\n');
    fprintf('  M3 (LANE B): 30 Hz GENERALIZED MOMENTUM OBSERVER VALIDATION SUITE\n');
    fprintf('  Version: 2.0.0-PRELIMINARY | Mode: %s\n', opt.Mode);
    fprintf('  Status:  PRELIMINARY (Pending frozen MS02P05 Simulink sweep signals)\n');
    fprintf('======================================================================\n\n');

    %% 1. Load Locked M1 Physical Parameters (Single Source of Truth)
    P = load_locked_m1_params();

    %% 2. Verify Passivity & Christoffel Identity: dD/dt = C + C'
    verify_christoffel_identity(P);

    %% 3. Ingest & Validate MAT Archives (or Explicit Synthetic Unit-Test Mode)
    if strcmpi(opt.Mode, 'mat_archive')
        arch_null = load_and_validate_mat_archive(opt.null_mat_path, P);
        arch_load = load_and_validate_mat_archive(opt.load_mat_path, P);
        verify_archive_pair_compatibility(arch_null, arch_load);
    else
        warning('m3_observer_suite:SyntheticUnitTestMode', ...
            ['Running in explicit SYNTHETIC_UNIT_TEST mode. Results from this ' ...
             'mode must NOT be reported as Simscape archive validation.']);
        [arch_null, arch_load] = build_synthetic_unit_test_pair(P);
    end

    %% 4. Observer Gain Freeze & Reproducibility Metadata
    k_frozen = opt.FrozenGain;
    KO_frozen = diag([k_frozen, k_frozen]);

    results = struct();
    results.metadata.code_version = '2.0.0-PRELIMINARY';
    results.metadata.status = 'PRELIMINARY (Pending frozen MS02P05 configuration sweep signals)';
    results.metadata.mode = opt.Mode;
    results.metadata.rng_seed = opt.RngSeed;
    results.metadata.rng_algorithm = 'Portable 32-bit Park-Miller LCG (a=16807, m=2^31-1) + Box-Muller';
    results.metadata.frozen_gains_s_inv = [k_frozen, k_frozen];
    results.metadata.observer_rate_Hz = P.Fs;
    results.metadata.observer_Ts_s = P.Ts;
    results.metadata.internal_substeps_M = opt.SubSteps;
    results.metadata.internal_dt_ms = 1000.0 * P.Ts / opt.SubSteps;
    results.metadata.arch_null_meta = rmfield(arch_null, {'t_raw', 'sig_raw', 't_30', 'trim_mask_30', 'sig_30'});
    results.metadata.arch_load_meta = rmfield(arch_load, {'t_raw', 'sig_raw', 't_30', 'trim_mask_30', 'sig_30'});

    %% 5. Diagnostic Check 0: Unmodified Raw .slx Archive (P.model_has_coulomb = false)
    fprintf('\n--- [Check 0] Raw Unmodified .slx Archive Check (model_has_coulomb = false) ---\n');
    results.raw_slx_diagnostic = run_raw_slx_diagnostic(arch_null, P, KO_frozen, opt.SubSteps);

    %% 6. Study 1: Internal Sub-Stepping Convergence (1.0 ms vs 0.5 ms vs Exact FOH)
    fprintf('\n--- [Study 1] Numerical Integration Convergence (k = %.1f s^-1, Case C) ---\n', k_frozen);
    results.convergence = run_convergence_study(arch_load, P, KO_frozen);

    %% 7. Study 2: Observer Gain Selection Sweep (k in [2, 55] s^-1)
    fprintf('\n--- [Study 2] Observer Gain Selection Sweep (k in [2, 55] s^-1) ---\n');
    k_grid = [2, 5, 10, 15, 20, 30, 45, 55];
    results.gain_sweep = run_gain_sweep(arch_null, arch_load, P, k_grid, opt.SubSteps, opt.RngSeed);

    %% 8. Study 3: Comparative Validation Suite (Test Cases A, B1, B2, C, D, E, F, G)
    fprintf('\n--- [Study 3] Comparative Validation Suite (Cases A, B1, B2, C, D, E, F, G) ---\n');
    results.suite = run_validation_suite(arch_null, arch_load, P, KO_frozen, opt.SubSteps, opt.RngSeed);

    %% 9. Study 4: Corrected Task-Space Jacobian & Equivalent Tip-Force Analysis
    fprintf('\n--- [Study 4] Task-Space Jacobian Conditioning & Tip-Force Critique ---\n');
    results.jacobian = run_jacobian_analysis(arch_load, P);

    %% 10. Save Reproducible Output Archive
    if opt.SaveResults
        save(opt.OutFile, 'results');
        fprintf('\nSaved reproducible M3 results struct to: %s\n', opt.OutFile);
    end

    fprintf('\n======================================================================\n');
    fprintf('  M3 Observer Suite (v2.0.0-PRELIMINARY) Completed Successfully.\n');
    fprintf('======================================================================\n');
end

%% ========================================================================
%  1. STRICT MAT ARCHIVE INGESTION & VALIDATION
%  ========================================================================

function arch = load_and_validate_mat_archive(filepath, P)
%LOAD_AND_VALIDATE_MAT_ARCHIVE Loads a recover_load.m MAT archive and validates all fields.
    if exist(filepath, 'file') ~= 2
        error('m3_observer_suite:FileNotFound', ...
            'Required MAT archive "%s" not found. Refusing to fall back to synthetic data.', filepath);
    end

    raw = load(filepath);
    if isfield(raw, 'results') && ~isfield(raw, 'R')
        error('m3_observer_suite:SummaryOnlyMatFile', ...
            ['Archive "%s" contains an M1 summary struct ("results") without time-series ' ...
             'arrays (t, q3, d4, tau3_meas, f4_meas). Supply a full M2 Simscape trajectory ' ...
             'archive such as M2_null.mat or M2_100kN_0p1111Hz_sp1p50.mat.'], filepath);
    end
    if ~isfield(raw, 'R') || ~isstruct(raw.R)
        error('m3_observer_suite:MissingRStruct', ...
            'Archive "%s" does not contain a valid top-level struct "R".', filepath);
    end
    R = raw.R;

    req_top = {'case', 'isNull', 'opt', 'params', 't', 'trimIdx', 'sig', 'prov'};
    for i = 1:numel(req_top)
        if ~isfield(R, req_top{i})
            error('m3_observer_suite:MissingField', ...
                'Archive "%s" struct R is missing required field "%s".', filepath, req_top{i});
        end
    end

    req_sig = {'q3', 'd4', 'q3d', 'd4d', 'q3dd', 'd4dd', ...
               'tau3_meas', 'tau3_model', 'e_tau3', ...
               'f4_meas', 'f4_model', 'e_f4', ...
               'Fx', 'Fy', 'Qq3_pred', 'Qd4_pred', 'ref3', 'ref4', 's', 'r'};
    for i = 1:numel(req_sig)
        if ~isfield(R.sig, req_sig{i})
            error('m3_observer_suite:MissingSignal', ...
                'Archive "%s" struct R.sig is missing required signal "%s".', filepath, req_sig{i});
        end
    end

    t_raw = double(R.t(:));
    N_raw = numel(t_raw);
    if N_raw < 100
        error('m3_observer_suite:InsufficientSamples', ...
            'Archive "%s" has only %d samples (minimum 100 required).', filepath, N_raw);
    end

    dt_vec = diff(t_raw);
    if any(dt_vec <= 0)
        error('m3_observer_suite:NonMonotonicTime', ...
            'Archive "%s" timestamp vector R.t is not strictly monotonic.', filepath);
    end
    dt_raw = median(dt_vec);
    if max(abs(dt_vec - dt_raw)) > 1e-6 * dt_raw
        error('m3_observer_suite:NonUniformTime', ...
            'Archive "%s" timestamp vector R.t is not uniformly sampled.', filepath);
    end
    fs_raw = 1.0 / dt_raw;

    for i = 1:numel(req_sig)
        fn = req_sig{i};
        v = double(R.sig.(fn)(:));
        if numel(v) ~= N_raw
            error('m3_observer_suite:DimensionMismatch', ...
                'Archive "%s" signal R.sig.%s has length %d (expected %d).', filepath, fn, numel(v), N_raw);
        end
        if ~isreal(v) || any(~isfinite(v))
            error('m3_observer_suite:InvalidSignalValues', ...
                'Archive "%s" signal R.sig.%s contains non-real, NaN, or Inf values.', filepath, fn);
        end
        R.sig.(fn) = v;
    end

    % Validate physical parameter consistency against shovel_params.m
    param_map = {'M_d', P.Md; 'I_zz', P.Izz; 'c', P.c; 'f_v3', P.fv3; 'f_v4', P.fv4; 'g', P.g};
    for i = 1:size(param_map, 1)
        pn = param_map{i, 1};
        pv = param_map{i, 2};
        if ~isfield(R.params, pn) || abs(double(R.params.(pn)) - pv) > 1e-6 * max(1.0, abs(pv))
            error('m3_observer_suite:ParameterDrift', ...
                'Archive "%s" R.params.%s disagrees with locked shovel_params.m value %.6g.', filepath, pn, pv);
        end
    end

    % Validate units and lever arm identities
    if max(abs(R.sig.q3)) > pi
        error('m3_observer_suite:UnitError', ...
            'Archive "%s" R.sig.q3 exceeds pi rad; check rad vs deg units.', filepath);
    end
    if max(abs(R.sig.r - (R.sig.d4 + P.c))) > 1e-9
        error('m3_observer_suite:LeverArmMismatch', ...
            'Archive "%s" R.sig.r does not equal d4 + c.', filepath);
    end
    if max(abs(R.sig.s - (R.sig.d4 + double(R.opt.Station)))) > 1e-9
        error('m3_observer_suite:StationMismatch', ...
            'Archive "%s" R.sig.s does not equal d4 + R.opt.Station.', filepath);
    end

    % Check whether Simscape .slx had Coulomb friction enabled during logging
    slx_res3 = max(abs(R.sig.e_tau3 - R.sig.ref3));
    slx_res4 = max(abs(R.sig.e_f4 - R.sig.ref4));
    slx_has_coulomb = (slx_res3 > 1.0) || (slx_res4 > 1.0);

    % Resample from 100 Hz archive grid onto 30 Hz observer timestamps t_k = k * T_s
    t_stop = double(R.opt.StopTime);
    t_trim = double(R.opt.TrimStart);
    N_30 = round(t_stop * P.Fs) + 1;
    t_30 = ((0:(N_30 - 1))' * P.Ts);
    trim_mask_30 = (t_30 >= (t_trim - 1e-9));

    sig_30 = struct();
    for i = 1:numel(req_sig)
        fn = req_sig{i};
        sig_30.(fn) = interp1(t_raw, R.sig.(fn), t_30, 'spline');
    end

    % Verify dynamic equation consistency at 30 Hz
    r_30 = sig_30.d4 + P.c;
    tau3_chk = (P.Izz + P.Md .* (r_30.^2)) .* sig_30.q3dd ...
             + 2.0 * P.Md .* r_30 .* sig_30.d4d .* sig_30.q3d ...
             + P.Md * P.g .* r_30 .* cos(sig_30.q3) ...
             + P.fv3 .* sig_30.q3d;
    spline_err3 = max(abs(tau3_chk(trim_mask_30) - sig_30.tau3_model(trim_mask_30)));

    arch = struct();
    arch.filepath = filepath;
    arch.case = char(R.case);
    arch.isNull = logical(R.isNull);
    arch.forceSrc = char(R.forceSrc);
    arch.alignNote = char(R.alignNote);
    arch.opt = R.opt;
    arch.prov = R.prov;
    arch.N_raw = N_raw;
    arch.fs_raw_Hz = fs_raw;
    arch.dt_raw_s = dt_raw;
    arch.N_30 = N_30;
    arch.N_trim_30 = sum(trim_mask_30);
    arch.t_trim_s = t_trim;
    arch.t_stop_s = t_stop;
    arch.slx_has_coulomb = slx_has_coulomb;
    arch.spline_consistency_Nm = spline_err3;
    arch.t_raw = t_raw;
    arch.sig_raw = R.sig;
    arch.t_30 = t_30;
    arch.trim_mask_30 = trim_mask_30;
    arch.sig_30 = sig_30;

    fprintf('[Archive Loaded] %s (case=%s, N_raw=%d @ %.1f Hz -> N_30=%d @ %.1f Hz, N_trim=%d, spline_err=%.2e Nm)\n', ...
        filepath, arch.case, arch.N_raw, arch.fs_raw_Hz, arch.N_30, P.Fs, arch.N_trim_30, arch.spline_consistency_Nm);
end

function verify_archive_pair_compatibility(arch_null, arch_load)
%VERIFY_ARCHIVE_PAIR_COMPATIBILITY Confirms M2_null and M2_100kN share identical kinematics.
    if numel(arch_null.t_30) ~= numel(arch_load.t_30) || max(abs(arch_null.t_30 - arch_load.t_30)) > 1e-12
        error('m3_observer_suite:IncompatibleArchives', ...
            'Null and loaded MAT archives do not share the same time base.');
    end
    q3_diff = max(abs(arch_null.sig_30.q3 - arch_load.sig_30.q3));
    d4_diff = max(abs(arch_null.sig_30.d4 - arch_load.sig_30.d4));
    if q3_diff > 1e-9 || d4_diff > 1e-9
        error('m3_observer_suite:TrajectoryMismatch', ...
            'Null and loaded MAT archives do not share identical joint trajectories (dq3=%.2e, dd4=%.2e).', ...
            q3_diff, d4_diff);
    end
end

%% ========================================================================
%  2. CORE OBSERVER FUNCTIONS (BRANCH A & BRANCH B) & PORTABLE RNG
%  ========================================================================

function [tau_hat_A, z_A] = run_branch_A_observer(t_k, p_k, h_A_k, KO, z0, M_sub, method)
%RUN_BRANCH_A_OBSERVER Friction-aware continuous-discrete momentum observer.
    N = length(t_k);
    z_A = zeros(N, 2);
    tau_hat_A = zeros(N, 2);
    z_A(1, :) = z0;
    k_vec = diag(KO)';
    tau_hat_A(1, :) = k_vec .* (p_k(1, :) - z_A(1, :));

    for k = 1:(N - 1)
        Ts = t_k(k+1) - t_k(k);
        u0 = h_A_k(k, :)   + k_vec .* p_k(k, :);
        u1 = h_A_k(k+1, :) + k_vec .* p_k(k+1, :);
        du = u1 - u0;

        if strcmpi(method, 'exact_foh')
            alpha = k_vec * Ts;
            E = exp(-alpha);
            z_A(k+1, :) = E .* z_A(k, :) ...
                        + (1.0 ./ k_vec) .* ((1.0 - E) .* u0 + (1.0 - (1.0 - E) ./ alpha) .* du);
        else
            dt = Ts / M_sub;
            zc = z_A(k, :);
            for m = 0:(M_sub - 1)
                if strcmpi(method, 'euler')
                    um = u0 + (m / M_sub) * du;
                    zc = zc + dt * (um - k_vec .* zc);
                elseif strcmpi(method, 'rk4')
                    ua = u0 + (m / M_sub) * du;
                    ub = u0 + ((m + 0.5) / M_sub) * du;
                    uc = u0 + ((m + 1.0) / M_sub) * du;
                    k1 = ua - k_vec .* zc;
                    k2 = ub - k_vec .* (zc + 0.5 * dt * k1);
                    k3_rk = ub - k_vec .* (zc + 0.5 * dt * k2);
                    k4_rk = uc - k_vec .* (zc + dt * k3_rk);
                    zc = zc + (dt / 6.0) * (k1 + 2.0*k2 + 2.0*k3_rk + k4_rk);
                end
            end
            z_A(k+1, :) = zc;
        end
        tau_hat_A(k+1, :) = k_vec .* (p_k(k+1, :) - z_A(k+1, :));
    end
end

function [tau_hat_B, z_B, bounds_B] = run_branch_B_observer(t_k, p_k, h_B_k, KO, z0, M_sub, method, P)
%RUN_BRANCH_B_OBSERVER Friction-uncertainty momentum observer.
    [tau_hat_B, z_B] = run_branch_A_observer(t_k, p_k, h_B_k, KO, z0, M_sub, method);
    bounds_B.q3_lower = tau_hat_B(:, 1) - P.fc3;
    bounds_B.q3_upper = tau_hat_B(:, 1) + P.fc3;
    bounds_B.d4_lower = tau_hat_B(:, 2) - P.fc4;
    bounds_B.d4_upper = tau_hat_B(:, 2) + P.fc4;
end

function Z = portable_randn_matrix(n_rows, n_cols, seed)
%PORTABLE_RANDN_MATRIX Deterministic Park-Miller LCG + Box-Muller normal generator.
%   Produces bit-for-bit identical N(0,1) variates in MATLAB and Python.
    total = n_rows * n_cols;
    n_pairs = floor((total + 1) / 2);
    s = double(bitand(uint32(seed), uint32(2147483647)));
    if s == 0, s = 1.0; end
    m = 2147483647.0;
    a = 16807.0;
    u1 = zeros(n_pairs, 1);
    u2 = zeros(n_pairs, 1);
    for i = 1:n_pairs
        s = mod(a * s, m);
        u1(i) = s / m;
        s = mod(a * s, m);
        u2(i) = s / m;
    end
    r = sqrt(-2.0 * log(u1));
    th = 2.0 * pi * u2;
    out = zeros(2 * n_pairs, 1);
    out(1:2:end) = r .* cos(th);
    out(2:2:end) = r .* sin(th);
    Z = reshape(out(1:total), [n_cols, n_rows])';
end

%% ========================================================================
%  3. PLANT PARAMETERS, MOMENTUM TERMS & METRIC EVALUATION
%  ========================================================================

function P = load_locked_m1_params()
%LOAD_LOCKED_M1_PARAMS Loads locked M1 parameters from shovel_params.m.
    if exist('shovel_params.m', 'file') == 2
        sp = shovel_params();
        P.Md  = double(sp.m);
        P.Izz = double(sp.Izz);
        P.c   = double(sp.c);
        P.fv3 = double(sp.fv3);
        P.fv4 = double(sp.fv4);
        P.fc3 = double(sp.fc3);
        P.fc4 = double(sp.fc4);
        P.g   = double(sp.g);
    else
        P.Md  = 54300.0;
        P.Izz = 287900.0;
        P.c   = -1.32;
        P.fv3 = 3800.0;
        P.fv4 = 1473.0;
        P.fc3 = 340.0;
        P.fc4 = 480.0;
        P.g   = 9.80665;
    end
    P.L_cog = 2.82;
    P.x_ref = 1.50;
    P.eps3  = 3.0e-4;
    P.eps4  = 1.0e-3;
    P.s_bail_offset = 1.50;  % Bail station s = d4 + 1.50 m (recover_load.m line 17)
    P.s_cog_offset  = -1.32; % COG station  s = d4 - 1.32 m (recover_load.m line 18)
    P.Fs    = 30.0;
    P.Ts    = 1.0 / P.Fs;
end

function [p, G_vec, Fv_vec, Fc_vec, CT_dq] = compute_momentum_terms(q3, d4, dq3, dd4, P)
%COMPUTE_MOMENTUM_TERMS Evaluates p, G(q), F_v*dq, F_c(dq), and C(q,dq)'*dq.
    r = d4 + P.c;
    D11 = P.Izz + P.Md .* (r.^2);
    D22 = P.Md * ones(size(d4));
    p = [D11 .* dq3, D22 .* dd4];
    G_vec = [P.Md * P.g .* r .* cos(q3), P.Md * P.g .* sin(q3)];
    Fv_vec = [P.fv3 .* dq3, P.fv4 .* dd4];
    Fc_vec = [P.fc3 .* tanh(dq3 ./ P.eps3), P.fc4 .* tanh(dd4 ./ P.eps4)];
    CT_dq = [zeros(size(q3)), P.Md .* r .* (dq3.^2)];
end

function verify_christoffel_identity(P)
%VERIFY_CHRISTOFFEL_IDENTITY Numerically verifies dD/dt = C + C' and skew-symmetry.
    r = 8.75 + P.c;
    dq3_t = 0.08; dd4_t = -0.45;
    dD = [2.0 * P.Md * r * dd4_t, 0; 0, 0];
    C  = [P.Md * r * dd4_t, P.Md * r * dq3_t; -P.Md * r * dq3_t, 0];
    err_pass = norm(dD - (C + C'), 'fro');
    S_skew = dD - 2.0 * C;
    err_skew = norm(S_skew + S_skew', 'fro');
    fprintf('[Verification] Christoffel Identity ||dD/dt - (C + C^T)||_F = %.3e\n', err_pass);
    fprintf('[Verification] Skew-Symmetry       ||(dD/dt - 2C) + (dD/dt - 2C)^T||_F = %.3e\n', err_skew);
    assert(err_pass < 1e-12 && err_skew < 1e-12, 'Christoffel passivity check failed.');
end

function m = compute_channel_metrics(t_k, tau_hat, tau_true, tau_filt, tau_other, fc_bound, eval_mask, is_sin, is_step)
%COMPUTE_CHANNEL_METRICS Computes separated channel metrics and 3 distinct coverage rates.
    tt  = t_k(eval_mask);
    est = tau_hat(eval_mask);
    tru = tau_true(eval_mask);
    flt = tau_filt(eval_mask);
    oth = tau_other(eval_mask);

    err = est - tru;
    err_lag = est - flt;
    fric_diff = abs(est - oth);

    m.RMSE   = sqrt(mean(err.^2));
    m.MAE    = mean(abs(err));
    m.Bias   = mean(err);
    m.MaxAbs = max(abs(err));

    rev_times = [5.10, 15.10, 25.10];
    hw = 0.15;
    pre_m = false(size(t_k)); dur_m = false(size(t_k)); post_m = false(size(t_k));
    for r_i = 1:numel(rev_times)
        tr = rev_times(r_i);
        pre_m  = pre_m  | (t_k >= tr - 3*hw & t_k < tr - hw);
        dur_m  = dur_m  | (t_k >= tr - hw   & t_k <= tr + hw);
        post_m = post_m | (t_k >  tr + hw   & t_k <= tr + 3*hw);
    end
    pre_idx  = eval_mask & pre_m;
    dur_idx  = eval_mask & dur_m;
    post_idx = eval_mask & post_m;

    m.RevPreMAE  = mean_or_zero(abs(tau_hat(pre_idx)  - tau_true(pre_idx)));
    m.RevDurMAE  = mean_or_zero(abs(tau_hat(dur_idx)  - tau_true(dur_idx)));
    m.RevDurMax  = max_or_zero(abs(tau_hat(dur_idx)   - tau_true(dur_idx)));
    m.RevPostMAE = mean_or_zero(abs(tau_hat(post_idx) - tau_true(post_idx)));

    % 3 separated coverage percentages:
    %   CovFricPct: |tau_hat_A - tau_hat_B| <= fc_bound (pure friction discrepancy bound)
    %   CovLagPct:  |tau_L_filt - tau_hat|  <= fc_bound (lag-compensated load interval)
    %   CovRawPct:  |tau_L      - tau_hat|  <= fc_bound (uncompensated raw load interval)
    m.CovFricPct = 100.0 * mean(fric_diff <= fc_bound + 1e-6);
    m.CovLagPct  = 100.0 * mean(abs(err_lag) <= fc_bound + 1e-6);
    m.CovRawPct  = 100.0 * mean(abs(err) <= fc_bound + 1e-6);

    m.AmpErrPct = NaN; m.PhaseLagMs = NaN; m.PhaseLagDeg = NaN; m.ConvTimeS = NaN;
    if is_sin
        omega = 2.0 * pi / 9.0;
        m.AmpErrPct = 100.0 * (max(abs(est)) - max(abs(tru))) / max(abs(tru));
        dtru = gradient(tru, tt) / omega;
        A_mat = [tru(:), -dtru(:)];
        c_fit = A_mat \ est(:);
        phi_rad = atan2(c_fit(2), c_fit(1));
        m.PhaseLagDeg = rad2deg(phi_rad);
        m.PhaseLagMs  = 1000.0 * phi_rad / omega;
    end
    if is_step
        t_step = 12.0;
        post_s = find(t_k >= t_step & eval_mask);
        step_mag = max(abs(tau_true(post_s)));
        settled = find(abs(tau_hat(post_s) - tau_true(post_s)) <= 0.02 * step_mag, 1, 'first');
        if ~isempty(settled)
            m.ConvTimeS = t_k(post_s(settled)) - t_step;
        end
    end
end

function v = mean_or_zero(x)
    if isempty(x), v = 0.0; else, v = mean(x); end
end

function v = max_or_zero(x)
    if isempty(x), v = 0.0; else, v = max(x); end
end

%% ========================================================================
%  4. STUDIES 0, 1, 2, 3, AND 4
%  ========================================================================

function diag0 = run_raw_slx_diagnostic(arch_null, P, KO, M_sub)
%RUN_RAW_SLX_DIAGNOSTIC Evaluates observers on raw M2_null.mat (model_has_coulomb = false).
    t_k = arch_null.t_30;
    mask = arch_null.trim_mask_30;
    s = arch_null.sig_30;
    [p_k, G_k, Fv_k, Fc_k, CT_k] = compute_momentum_terms(s.q3, s.d4, s.q3d, s.d4d, P);
    tau_slx = [s.tau3_meas, s.f4_meas];
    hA_raw = tau_slx - G_k - Fv_k + CT_k - Fc_k;
    hB_raw = tau_slx - G_k - Fv_k + CT_k;
    [estA, ~] = run_branch_A_observer(t_k, p_k, hA_raw, KO, p_k(1,:), M_sub, 'rk4');
    [estB, ~] = run_branch_A_observer(t_k, p_k, hB_raw, KO, p_k(1,:), M_sub, 'rk4');
    diag0.BranchA_q3_RMSE_Nm = rms(estA(mask, 1));
    diag0.BranchA_d4_RMSE_N  = rms(estA(mask, 2));
    diag0.BranchB_q3_RMSE_Nm = rms(estB(mask, 1));
    diag0.BranchB_d4_RMSE_N  = rms(estB(mask, 2));
    fprintf('  Unmodified M2_null.mat (P.model_has_coulomb=false): Branch B RMSE = [%.2f Nm, %.2f N], Branch A RMSE = [%.2f Nm, %.2f N]\n', ...
        diag0.BranchB_q3_RMSE_Nm, diag0.BranchB_d4_RMSE_N, diag0.BranchA_q3_RMSE_Nm, diag0.BranchA_d4_RMSE_N);
end

function conv = run_convergence_study(arch_load, P, KO)
%RUN_CONVERGENCE_STUDY Evaluates 1.0 ms vs 0.5 ms vs 0.1 ms vs Exact FOH on Case C.
    t_k = arch_load.t_30;
    mask = arch_load.trim_mask_30;
    s = arch_load.sig_30;
    [p_k, G_k, Fv_k, Fc_k, CT_k] = compute_momentum_terms(s.q3, s.d4, s.q3d, s.d4d, P);
    Q_pred = [s.Qq3_pred, s.Qd4_pred];
    tau_a_k = [s.tau3_meas, s.f4_meas] + Fc_k;
    h_A_k = tau_a_k - G_k - Fv_k + CT_k - Fc_k;

    [tau_foh, ~]  = run_branch_A_observer(t_k, p_k, h_A_k, KO, p_k(1,:), 1,   'exact_foh');
    [tau_m1, ~]   = run_branch_A_observer(t_k, p_k, h_A_k, KO, p_k(1,:), 1,   'euler');
    [tau_m33, ~]  = run_branch_A_observer(t_k, p_k, h_A_k, KO, p_k(1,:), 33,  'euler');
    [tau_m67, ~]  = run_branch_A_observer(t_k, p_k, h_A_k, KO, p_k(1,:), 67,  'euler');
    [tau_m333, ~] = run_branch_A_observer(t_k, p_k, h_A_k, KO, p_k(1,:), 333, 'euler');
    [tau_rk33, ~] = run_branch_A_observer(t_k, p_k, h_A_k, KO, p_k(1,:), 33,  'rk4');
    [tau_rk67, ~] = run_branch_A_observer(t_k, p_k, h_A_k, KO, p_k(1,:), 67,  'rk4');

    schemes = {'Macro Euler (33.33 ms, M=1)', 1,   tau_m1; ...
               'Euler 1.0 ms (M=33)',         33,  tau_m33; ...
               'Euler 0.5 ms (M=67)',         67,  tau_m67; ...
               'Euler 0.1 ms (M=333)',        333, tau_m333; ...
               'RK4 1.0 ms (M=33)',           33,  tau_rk33; ...
               'RK4 0.5 ms (M=67)',           67,  tau_rk67; ...
               'Exact FOH (Analytical)',      1,   tau_foh};

    fprintf('%-28s | %14s | %14s | %14s | %14s\n', ...
        'Scheme', 'RMSE3 vs FOH', 'RMSE4 vs FOH', 'RMSE3 vs True', 'RMSE4 vs True');
    fprintf('%s\n', repmat('-', 1, 94));
    for i = 1:size(schemes, 1)
        name = schemes{i, 1};
        M_v  = schemes{i, 2};
        est  = schemes{i, 3};
        r3_foh  = rms(est(mask, 1) - tau_foh(mask, 1));
        r4_foh  = rms(est(mask, 2) - tau_foh(mask, 2));
        r3_true = rms(est(mask, 1) - Q_pred(mask, 1));
        r4_true = rms(est(mask, 2) - Q_pred(mask, 2));
        fprintf('%-28s | %11.4e Nm | %11.4e N  | %11.2f Nm | %11.2f N\n', ...
            name, r3_foh, r4_foh, r3_true, r4_true);
        conv(i).scheme = name;
        conv(i).M = M_v;
        conv(i).dt_ms = 1000.0 * P.Ts / M_v;
        conv(i).RMSE3_vs_FOH = r3_foh; conv(i).RMSE4_vs_FOH = r4_foh;
        conv(i).RMSE3_vs_True = r3_true; conv(i).RMSE4_vs_True = r4_true;
    end
end

function sweep = run_gain_sweep(arch_null, arch_load, P, k_grid, M_sub, rng_seed)
%RUN_GAIN_SWEEP Multi-objective gain sweep across Case C, Case D, Case A, and Case G.
    t_k  = arch_null.t_30;
    mask = arch_null.trim_mask_30;
    sn   = arch_null.sig_30;
    sl   = arch_load.sig_30;
    [p_k, G_k, Fv_k, Fc_k, CT_k] = compute_momentum_terms(sn.q3, sn.d4, sn.q3d, sn.d4d, P);

    Q_pred = [sl.Qq3_pred, sl.Qd4_pred];
    tau_a_load = [sl.tau3_meas, sl.f4_meas] + Fc_k;
    tau_a_null = [sn.tau3_meas, sn.f4_meas] + Fc_k;
    tau_step = [300000.0 * double(t_k >= 12.0), 60000.0 * double(t_k >= 12.0)];

    Z_noise = portable_randn_matrix(length(t_k), 6, rng_seed);
    n_q3  = 5.0e-4 * Z_noise(:, 1); n_d4  = 1.0e-3 * Z_noise(:, 2);
    n_dq3 = 3.0e-3 * Z_noise(:, 3); n_dd4 = 5.0e-3 * Z_noise(:, 4);
    n_t3  = 1500.0 * Z_noise(:, 5); n_f4  = 300.0  * Z_noise(:, 6);
    [p_n, G_n, Fv_n, Fc_n, CT_n] = compute_momentum_terms(sn.q3+n_q3, sn.d4+n_d4, sn.q3d+n_dq3, sn.d4d+n_dd4, P);

    hA_sin   = tau_a_load - G_k - Fv_k + CT_k - Fc_k;
    hA_null  = tau_a_null - G_k - Fv_k + CT_k - Fc_k;
    hA_step  = (tau_a_null - tau_step) - G_k - Fv_k + CT_k - Fc_k;
    hA_noisy = (tau_a_load + [n_t3, n_f4]) - G_n - Fv_n + CT_n - Fc_n;

    fprintf('%6s | %8s | %8s | %12s | %12s | %10s | %14s\n', ...
        'k[1/s]', 'tau_O[ms]', 'k*Ts', 'SinRMSE3[kNm]', 'SinRMSE4[kN]', 'StepConv[s]', 'NoisyRMSE3[kNm]');
    fprintf('%s\n', repmat('-', 1, 84));

    for i = 1:length(k_grid)
        kv = k_grid(i);
        KO = diag([kv, kv]);
        [est_c, ~] = run_branch_A_observer(t_k, p_k, hA_sin,   KO, p_k(1,:), M_sub, 'rk4');
        [est_z, ~] = run_branch_A_observer(t_k, p_k, hA_null,  KO, p_k(1,:), M_sub, 'rk4');
        [est_s, ~] = run_branch_A_observer(t_k, p_k, hA_step,  KO, p_k(1,:), M_sub, 'rk4');
        [est_n, ~] = run_branch_A_observer(t_k, p_n, hA_noisy, KO, p_n(1,:), M_sub, 'rk4');

        mc3 = compute_channel_metrics(t_k, est_c(:,1), Q_pred(:,1), Q_pred(:,1), est_c(:,1), P.fc3, mask, true, false);
        mc4 = compute_channel_metrics(t_k, est_c(:,2), Q_pred(:,2), Q_pred(:,2), est_c(:,2), P.fc4, mask, true, false);
        ms3 = compute_channel_metrics(t_k, est_s(:,1), tau_step(:,1), tau_step(:,1), est_s(:,1), P.fc3, mask, false, true);
        mz3 = compute_channel_metrics(t_k, est_z(:,1), zeros(size(t_k)), zeros(size(t_k)), est_z(:,1), P.fc3, mask, false, false);

        sweep(i).k = kv;
        sweep(i).tau_O_ms = 1000.0 / kv;
        sweep(i).k_Ts = kv * P.Ts;
        sweep(i).Sin_RMSE3_kNm = mc3.RMSE / 1e3;
        sweep(i).Sin_RMSE4_kN  = mc4.RMSE / 1e3;
        sweep(i).Sin_Lag_ms    = mc3.PhaseLagMs;
        sweep(i).Step_Conv_s   = ms3.ConvTimeS;
        sweep(i).Zero_RMSE3_Nm = mz3.RMSE;
        sweep(i).Zero_RevMax3_Nm = mz3.RevDurMax;
        sweep(i).Noisy_RMSE3_kNm = rms(est_n(mask, 1) - Q_pred(mask, 1)) / 1e3;
        sweep(i).Noisy_RMSE4_kN  = rms(est_n(mask, 2) - Q_pred(mask, 2)) / 1e3;

        fprintf('%6.1f | %9.1f | %8.3f | %13.2f | %12.2f | %11.3f | %15.2f\n', ...
            kv, sweep(i).tau_O_ms, sweep(i).k_Ts, sweep(i).Sin_RMSE3_kNm, ...
            sweep(i).Sin_RMSE4_kN, sweep(i).Step_Conv_s, sweep(i).Noisy_RMSE3_kNm);
    end
end

function suite = run_validation_suite(arch_null, arch_load, P, KO, M_sub, rng_seed)
%RUN_VALIDATION_SUITE Executes Test Cases A, B1, B2, C, D, E, F, and G.
    t_k  = arch_null.t_30;
    trim_mask = arch_null.trim_mask_30;
    unidir_mask = (t_k >= 15.5) & (t_k <= 24.5);
    sn = arch_null.sig_30;
    sl = arch_load.sig_30;
    [p_k, G_k, Fv_k, Fc_k, CT_k] = compute_momentum_terms(sn.q3, sn.d4, sn.q3d, sn.d4d, P);

    tau_slx_null = [sn.tau3_meas, sn.f4_meas];
    tau_slx_load = [sl.tau3_meas, sl.f4_meas];
    Q_pred_load  = [sl.Qq3_pred,  sl.Qd4_pred];

    env = exp(-0.5 * ((t_k - 16.0) / 4.5).^2);
    tau_const = [-250000.0 * ones(size(t_k)), -50000.0 * ones(size(t_k))];
    tau_step  = [300000.0 * double(t_k >= 12.0), 60000.0 * double(t_k >= 12.0)];
    tau_tv    = [-320000.0 .* env .* (1.0 + 0.25*sin(2*pi*0.35*t_k)), ...
                 -65000.0  .* env .* (1.0 + 0.20*cos(2*pi*0.35*t_k))];
    tau_rev   = [1500.0 * sin(2*pi*0.18*t_k), 2000.0 * cos(2*pi*0.18*t_k)];

    Z_noise = portable_randn_matrix(length(t_k), 6, rng_seed);
    n_q3  = 5.0e-4 * Z_noise(:, 1); n_d4  = 1.0e-3 * Z_noise(:, 2);
    n_dq3 = 3.0e-3 * Z_noise(:, 3); n_dd4 = 5.0e-3 * Z_noise(:, 4);
    n_t3  = 1500.0 * Z_noise(:, 5); n_f4  = 300.0  * Z_noise(:, 6);
    [p_n, G_n, Fv_n, Fc_n, CT_n] = compute_momentum_terms(sn.q3+n_q3, sn.d4+n_d4, sn.q3d+n_dq3, sn.d4d+n_dd4, P);

    cases = {
        'A_Zero_M2_null',             zeros(length(t_k), 2), trim_mask,   false, false, false;
        'B1_Constant_Reversing',      tau_const,             trim_mask,   false, false, false;
        'B2_Constant_Unidirectional', tau_const,             unidir_mask, false, false, false;
        'C_Sinusoidal_M2_100kN',      Q_pred_load,           trim_mask,   true,  false, false;
        'D_Step',                     tau_step,              trim_mask,   false, true,  false;
        'E_TimeVarying',              tau_tv,                trim_mask,   false, false, false;
        'F_Reversal_Focused',         tau_rev,               trim_mask,   false, false, false;
        'G_Synthetic_Noise_Stress',   Q_pred_load,           trim_mask,   true,  false, true
    };

    fprintf('%-26s | %-3s | %10s | %10s | %10s | %8s | %8s | %8s\n', ...
        'Test Case', 'Br', 'RMSE3[Nm]', 'Bias3[Nm]', 'RMSE4[N]', 'CovFric', 'CovLag', 'CovRaw');
    fprintf('%s\n', repmat('-', 1, 102));

    for c = 1:size(cases, 1)
        cname   = cases{c, 1};
        tau_L   = cases{c, 2};
        ev_mask = cases{c, 3};
        is_sin  = cases{c, 4};
        is_stp  = cases{c, 5};
        is_nsy  = cases{c, 6};

        if strcmp(cname, 'C_Sinusoidal_M2_100kN') || strcmp(cname, 'G_Synthetic_Noise_Stress')
            tau_a_clean = tau_slx_load + Fc_k;
        else
            tau_a_clean = (tau_slx_null + Fc_k) - tau_L;
        end

        if is_nsy
            p_in = p_n;
            tau_a_in = tau_a_clean + [n_t3, n_f4];
            hA_in = tau_a_in - G_n - Fv_n + CT_n - Fc_n;
            hB_in = tau_a_in - G_n - Fv_n + CT_n;
        else
            p_in = p_k;
            hA_in = tau_a_clean - G_k - Fv_k + CT_k - Fc_k;
            hB_in = tau_a_clean - G_k - Fv_k + CT_k;
        end

        [est_A, ~] = run_branch_A_observer(t_k, p_in, hA_in, KO, p_in(1,:), M_sub, 'rk4');
        [est_B, ~, bnd_B] = run_branch_B_observer(t_k, p_in, hB_in, KO, p_in(1,:), M_sub, 'rk4', P);
        [tau_L_filt, ~] = run_branch_A_observer(t_k, zeros(size(p_k)), -tau_L, KO, [0, 0], 1, 'exact_foh');

        mA3 = compute_channel_metrics(t_k, est_A(:,1), tau_L(:,1), tau_L_filt(:,1), est_B(:,1), P.fc3, ev_mask, is_sin, is_stp);
        mA4 = compute_channel_metrics(t_k, est_A(:,2), tau_L(:,2), tau_L_filt(:,2), est_B(:,2), P.fc4, ev_mask, is_sin, is_stp);
        mB3 = compute_channel_metrics(t_k, est_B(:,1), tau_L(:,1), tau_L_filt(:,1), est_A(:,1), P.fc3, ev_mask, is_sin, is_stp);
        mB4 = compute_channel_metrics(t_k, est_B(:,2), tau_L(:,2), tau_L_filt(:,2), est_A(:,2), P.fc4, ev_mask, is_sin, is_stp);

        fprintf('%-26s | %-3s | %10.2f | %10.2f | %10.2f | %7.1f%% | %7.1f%% | %7.1f%%\n', ...
            cname, 'A', mA3.RMSE, mA3.Bias, mA4.RMSE, mA3.CovFricPct, mA3.CovLagPct, mA3.CovRawPct);
        fprintf('%-26s | %-3s | %10.2f | %10.2f | %10.2f | %7.1f%% | %7.1f%% | %7.1f%%\n', ...
            cname, 'B', mB3.RMSE, mB3.Bias, mB4.RMSE, mB3.CovFricPct, mB3.CovLagPct, mB3.CovRawPct);

        suite.(cname).n_eval_samples = sum(ev_mask);
        suite.(cname).BranchA_q3 = mA3; suite.(cname).BranchA_d4 = mA4;
        suite.(cname).BranchB_q3 = mB3; suite.(cname).BranchB_d4 = mB4;
        suite.(cname).est_A = est_A;    suite.(cname).est_B = est_B;
        suite.(cname).bounds_B = bnd_B; suite.(cname).tau_L_true = tau_L;
        suite.(cname).tau_L_filt = tau_L_filt;
    end
end

function jac = run_jacobian_analysis(arch_load, P)
%RUN_JACOBIAN_ANALYSIS Verifies J_s(q) = R(q3)*Pi*diag(s, 1) and F_equiv = J_s^{-T}*tau.
    s = arch_load.sig_30;
    s_bail = s.d4 + P.s_bail_offset; % d4 + 1.50 m
    s_cog  = s.d4 + P.s_cog_offset;  % d4 - 1.32 m

    % Forward mapping: Q = J_s(q)' * F = [s*(Fy*cos(q3) - Fx*sin(q3)); Fx*cos(q3) + Fy*sin(q3)]
    Q3_jac = s_bail .* (s.Fy .* cos(s.q3) - s.Fx .* sin(s.q3));
    Q4_jac = s.Fx .* cos(s.q3) + s.Fy .* sin(s.q3);
    jac.forward_err_Nm = max(abs(Q3_jac - s.Qq3_pred));
    jac.forward_err_N  = max(abs(Q4_jac - s.Qd4_pred));

    % Inverse-transpose mapping: F_equiv = J_s(q)^{-T} * Q = R(q3) * Pi * diag(1/s, 1) * Q
    Fx_rec = -(Q3_jac ./ s_bail) .* sin(s.q3) + Q4_jac .* cos(s.q3);
    Fy_rec =  (Q3_jac ./ s_bail) .* cos(s.q3) + Q4_jac .* sin(s.q3);
    jac.inv_err_Fx_N = max(abs(Fx_rec - s.Fx));
    jac.inv_err_Fy_N = max(abs(Fy_rec - s.Fy));

    jac.d4_archive_range_m     = [min(s.d4), max(s.d4)];
    jac.s_bail_archive_range_m = [min(s_bail), max(s_bail)];
    jac.s_cog_archive_range_m  = [min(s_cog), max(s_cog)];
    jac.cond_J_bail_range      = [min(s_bail), max(s_bail)];
    jac.cond_J_cog_range       = [min(s_cog), max(s_cog)];
    jac.F_equiv_bail_coulomb_N = [sqrt((P.fc3 / max(s_bail))^2 + P.fc4^2), ...
                                  sqrt((P.fc3 / min(s_bail))^2 + P.fc4^2)];

    fprintf('[Jacobian] Verified J_s(q) = R(q3)*Pi*diag(s, 1) on %s:\n', arch_load.case);
    fprintf('  Forward mapping error ||J_s^T F - Q_pred||_inf = [%.3e Nm, %.3e N]\n', ...
        jac.forward_err_Nm, jac.forward_err_N);
    fprintf('  Inverse mapping error ||J_s^{-T} Q_pred - F||_inf = [%.3e N, %.3e N]\n', ...
        jac.inv_err_Fx_N, jac.inv_err_Fy_N);
    fprintf('  Archive d4 in [%.4f, %.4f] m -> s_bail in [%.4f, %.4f] m, s_COG in [%.4f, %.4f] m\n', ...
        jac.d4_archive_range_m(1), jac.d4_archive_range_m(2), ...
        jac.s_bail_archive_range_m(1), jac.s_bail_archive_range_m(2), ...
        jac.s_cog_archive_range_m(1), jac.s_cog_archive_range_m(2));
    fprintf('  Equivalent Bail Tip-Force Coulomb Floor ||J_bail^{-T} F_c||_2 in [%.2f, %.2f] N\n', ...
        jac.F_equiv_bail_coulomb_N(1), jac.F_equiv_bail_coulomb_N(2));
end

function [arch_null, arch_load] = build_synthetic_unit_test_pair(P)
%BUILD_SYNTHETIC_UNIT_TEST_PAIR Explicit synthetic unit-test mode (never used as fallback).
    t_30 = ((0:900)' * P.Ts);
    w = pi / 10.0;
    tau = 0.05;
    gain = 1.0 / (1.0 + (w * tau)^2);
    lag = 2.0 * atan(w * tau);
    q3  = deg2rad(45.0) + deg2rad(15.0) * gain * sin(w * t_30 - lag);
    q3d = deg2rad(15.0) * w * gain * cos(w * t_30 - lag);
    q3dd = -deg2rad(15.0) * (w^2) * gain * sin(w * t_30 - lag);
    d4  = 8.75 + 2.0 * gain * sin(w * t_30 - lag);
    d4d = 2.0 * w * gain * cos(w * t_30 - lag);
    d4dd = -2.0 * (w^2) * gain * sin(w * t_30 - lag);
    r = d4 + P.c;
    s_bail = d4 + P.s_bail_offset;
    tau3_m = (P.Izz + P.Md .* r.^2) .* q3dd + 2*P.Md.*r.*d4d.*q3d + P.Md*P.g.*r.*cos(q3) + P.fv3.*q3d;
    f4_m   = P.Md .* d4dd - P.Md .* r .* (q3d.^2) + P.Md*P.g.*sin(q3) + P.fv4.*d4d;
    Fy = 100000.0 * sin((2*pi/9.0) * t_30);
    Fx = zeros(size(t_30));
    Qq3 = s_bail .* Fy .* cos(q3);
    Qd4 = Fy .* sin(q3);

    sig_n = struct('q3',q3,'d4',d4,'q3d',q3d,'d4d',d4d,'q3dd',q3dd,'d4dd',d4dd, ...
        'tau3_meas',tau3_m,'tau3_model',tau3_m,'e_tau3',zeros(size(t_30)), ...
        'f4_meas',f4_m,'f4_model',f4_m,'e_f4',zeros(size(t_30)), ...
        'Fx',Fx,'Fy',zeros(size(t_30)),'Qq3_pred',zeros(size(t_30)),'Qd4_pred',zeros(size(t_30)), ...
        'ref3',zeros(size(t_30)),'ref4',zeros(size(t_30)),'s',s_bail,'r',r);
    sig_l = sig_n;
    sig_l.Fy = Fy; sig_l.Qq3_pred = Qq3; sig_l.Qd4_pred = Qd4;
    sig_l.ref3 = -Qq3; sig_l.ref4 = -Qd4;
    sig_l.tau3_meas = tau3_m - Qq3; sig_l.f4_meas = f4_m - Qd4;

    arch_null = struct('filepath','SYNTHETIC_UNIT_TEST','case','SYNTHETIC_NULL','isNull',true, ...
        't_raw',t_30,'sig_raw',sig_n,'t_30',t_30,'trim_mask_30',(t_30 >= 5.0),'sig_30',sig_n);
    arch_load = struct('filepath','SYNTHETIC_UNIT_TEST','case','SYNTHETIC_LOAD','isNull',false, ...
        't_raw',t_30,'sig_raw',sig_l,'t_30',t_30,'trim_mask_30',(t_30 >= 5.0),'sig_30',sig_l);
end
